    3	namespace Modules\AI\Domain\Decision;
    4	
    5	use Modules\AI\Models\AiProfile;
    6	use OGame\GameObjects\Models\UnitObject;
    7	use OGame\GameObjects\Models\Units\UnitCollection;
    8	use OGame\Models\Resources;
    9	use OGame\Models\UnitQueue;
   10	use OGame\Services\ObjectService;
   11	use OGame\Services\PlanetService;
   12	use OGame\Services\PlayerService;
   13	use RuntimeException;
   14	use Symfony\Component\Yaml\Yaml;
   15	
   16	/**
   17	 * The composition half of the defence decision: which unit the account's doctrine is most behind on.
   18	 *
   19	 * `QueueableUnitPlanner` answers *whether* a planet should hold defence; this answers *what shape*
   20	 * that wall takes. The shape is a sourced player doctrine — an anchor unit plus a ratio of the other
   21	 * units per anchor — read from `resources/behavior/defence-doctrines.yaml` at planning time. Ratios
   22	 * live in that file only; nothing here restates one.
   23	 *
   24	 * The units are host objects resolved from the defence registry, so a mod-added defence piece is
   25	 * usable with no edit here, and a doctrine naming a unit the host does not have is an error rather
   26	 * than a silent default. Nothing here decides that more defence is wanted — that is the need
   27	 * evaluator's business. When a need arrives it is the *size* the wall is built to, in the value the
   28	 * evaluator states; how many units that is stays the doctrine's business, because the ratio and the
   29	 * host's prices are here.
   30	 */
   31	class DefenseCompositionPlanner
   32	{
   33	    /** The doctrine an account without a persisted belief builds. */
   34	    private const DEFAULT_DOCTRINE = 'balanced';
   35	
   36	    private const DOCTRINE_FILE = 'resources/behavior/defence-doctrines.yaml';
   37	
   38	    /** Metal-equivalent weights, the same ones the rest of the module prices objects with. */
   39	    private const CRYSTAL_WEIGHT = 1.5;
   40	
   41	    private const DEUTERIUM_WEIGHT = 2.0;
   42	
   43	    public function __construct(private ?string $doctrineFile = null)
   44	    {
   45	    }
   46	
   47	    /**
   48	     * The doctrine's next unit for this planet, or null when the wall already matches its ratio or
   49	     * nothing in the gap can legally be queued.
   50	     *
   51	     * A need raises the wall the ratio is applied to: the doctrine's stated anchor is the wall an
   52	     * account builds with nothing at risk, and one that has something to lose builds further out.
   53	     */
   54	    public function plan(PlayerService $player, PlanetService $planet, ?DefenseNeed $need = null): ?DefenseComposition
   55	    {
   56	        $doctrines = $this->doctrines();
   57	        $defenceObjects = $this->defenceObjectsByMachineName();
   58	
   59	        $key = $this->afterStopRule($doctrines, $defenceObjects, $this->doctrineKey($player), $planet);
   60	
   61	        $doctrine = $doctrines[$key] ?? throw new RuntimeException(
   62	            sprintf('defence-doctrines: the doctrine "%s" is not defined.', $key)
   63	        );
   64	
   65	        $anchorCount = (int) $doctrine['anchor']['count'];
   66	        if ($anchorCount <= 0) {
   67	            throw new RuntimeException(sprintf('defence-doctrines: the doctrine "%s" has no anchor count.', $key));
   68	        }
   69	
   70	        $anchor = $this->resolveUnit($doctrine['anchor']['unit'], $defenceObjects);
   71	
   72	        // The wall is what the planet holds plus what it has already paid for and is waiting on.
   73	        // The yard builds far slower than a fast universe pays, so a target measured on built units
   74	        // alone is re-bought every session and the queue grows without bound: measured live
   75	        // 29 Sep 2026, 21.8M paid rocket launchers pending on grand while 2.9M were built in a day.
   76	        $current = $planet->getDefenseUnits();
   77	        $pending = $this->pendingDefence($planet);
   78	        $held = fn (string $machineName): int => $current->getAmountByMachineName($machineName)
   79	            + ($pending[$machineName] ?? 0);
   80	
   81	        // One planet's wall stops at the ceiling the behaviour file states. Exposure has no bound
   82	        // of its own, and the ratio applied to a wall that already exists grows with it, so without
   83	        // this the account's whole defence budget lands on one planet (measured live 30 Sep 2026:
   84	        // 1,285,633 defence units on a single planet, 60+ over the ceiling).
   85	        $ceiling = $this->ceilingUnits();
   86	        $remaining = $ceiling === null ? null : $ceiling - $this->heldDefenseUnits($current, $pending);
   87	        if ($remaining !== null && $remaining <= 0) {
   88	            return null;
   89	        }
   90	
   91	        // The wall's size in doctrine layers. A wall whose anchor is still below the doctrine's
   92	        // stated count is built to that stated wall; a larger anchor scales every ratio with it, so
   93	        // a bigger wall is the same doctrine rather than a different one. A need extends that
   94	        // further: what the account stands to lose, priced against what one layer of this doctrine
   95	        // costs, is how far out the wall is built.
   96	        $scale = max($held($anchor->machine_name), $anchorCount);
   97	
   98	        if ($need !== null) {
   99	            $scale = max($scale, (int) ceil($need->defenceValue / $this->layerValue($anchor, $doctrine, $defenceObjects)));
  100	        }
  101	
  102	        $best = null;
  103	        $bestBehind = 0.0;
  104	
  105	        foreach ($doctrine['ratio'] as $name => $ratio) {
  106	            $unit = $this->resolveUnit($name, $defenceObjects);
  107	            $target = (int) ceil($ratio * $scale / $anchorCount);
  108	            $have = $held($unit->machine_name);
  109	
  110	            if ($have >= $target) {
  111	                continue;
  112	            }
  113	
  114	            // Largest shortfall as a fraction of the target; the doctrine's first entry wins a tie.
  115	            $behind = ($target - $have) / $target;
  116	            if ($behind <= $bestBehind) {
  117	                continue;
  118	            }
  119	
  120	            $affordable = $this->queueableAmount($planet, $unit);
  121	            if ($affordable <= 0) {
  122	                continue;
  123	            }
  124	
  125	            $best = app()->makeWith(DefenseComposition::class, [
  126	                'unit' => $unit,
  127	                'amount' => $remaining === null ? min($target - $have, $affordable) : min($target - $have, $affordable, $remaining),
  128	                'doctrine' => $key,
  129	                'reason' => 'defense:'.$key.':'.$unit->machine_name,
  130	            ]);
  131	            $bestBehind = $behind;
  132	        }
  133	
  134	        return $best;
  135	    }
  136	
  137	    /**
  138	     * The doctrine key the account's persisted belief builds to, or the default when it has none.
  139	     */
  140	    private function doctrineKey(PlayerService $player): string
  141	    {
  142	        $profile = AiProfile::query()->where('player_id', $player->getId())->first();
  143	
  144	        return $profile?->defense_doctrine?->doctrineKey() ?? self::DEFAULT_DOCTRINE;
  145	    }
  146	
  147	    /**
  148	     * How many more defence units this planet may hold before it reaches the ceiling the behaviour
  149	     * file states, or null when the file states none. The planner's own gate reads the same number;
  150	     * the unit executor asks again because a session backlog lets several sessions order the same
  151	     * shortfall before any of those orders reaches the yard.
  152	     */
  153	    public function remainingCeiling(PlanetService $planet): ?int
  154	    {
  155	        $ceiling = $this->ceilingUnits();
  156	
  157	        return $ceiling === null
  158	            ? null
  159	            : $ceiling - $this->heldDefenseUnits($planet->getDefenseUnits(), $this->pendingDefence($planet));
  160	    }
  161	
  162	    /**
  163	     * Defence this planet has already paid for and is waiting on, by machine name.
  164	     *
  165	     * The host takes the whole price when the order is placed, so an order in the yard is a wall the
  166	     * account already owns; without it the doctrine buys the same shortfall again every session.
  167	     * One read per planet per plan, resolved through the host's object registry so a mod-added
  168	     * defence piece needs no name here.
  169	     *
  170	     * @return array<string, int>
  171	     */
  172	    private function pendingDefence(PlanetService $planet): array
  173	    {
  174	        $pending = [];
  175	
  176	        $rows = UnitQueue::query()
  177	            ->where('planet_id', $planet->getPlanetId())
  178	            ->where('processed', 0)
  179	            ->selectRaw('object_id, SUM(object_amount) AS amount')
  180	            ->groupBy('object_id')
  181	            ->pluck('amount', 'object_id');
  182	
  183	        foreach ($rows as $objectId => $amount) {
  184	            $machineName = ObjectService::getObjectById((int) $objectId)->machine_name;
  185	            $pending[$machineName] = (int) $amount;
  186	        }
  187	
  188	        return $pending;
  189	    }
  190	
  191	    /**
  192	     * The ceiling on the defence units one planet may hold, read from the behaviour file, or null
  193	     * when the file states none. The number is policy, not a price or a unit: a file without it
  194	     * deliberately caps nothing, which is what a doctrine fixture written for a unit test means.
  195	     */
  196	    private function ceilingUnits(): ?int
  197	    {
  198	        $parsed = Yaml::parseFile($this->doctrineFile ?? module_path('AI', self::DOCTRINE_FILE));
  199	        $units = is_array($parsed) ? ($parsed['standing_wall_ceiling']['units'] ?? null) : null;
  200	
  201	        return is_numeric($units) && (int) $units > 0 ? (int) $units : null;
  202	    }
  203	
  204	    /**
  205	     * The defence units a planet already holds, built or waiting in the yard: what is left of the
  206	     * ceiling. Ships in the same queue do not count, because the ceiling is about the wall.
  207	     *
  208	     * @param  array<string, int>  $pending
  209	     */
  210	    private function heldDefenseUnits(UnitCollection $current, array $pending): int
  211	    {
  212	        $total = 0;
  213	
  214	        foreach ($this->defenceObjectsByMachineName() as $machineName => $object) {
  215	            $total += $current->getAmountByMachineName($machineName) + ($pending[$machineName] ?? 0);
  216	        }
  217	
  218	        return $total;
  219	    }
  220	
  221	    /**
  222	     * The doctrine the wall moves to once it outgrows the one it started in.
  223	     *
  224	     * The handover is stated in the doctrine file ("swap to X once the wall passes N ..."), so the
  225	     * target and the threshold are read from there rather than repeated as constants here.
  226	     *
  227	     * ponytail: the sentence is matched by shape, so rewording it silently disables the handover.
  228	     * Upgrade path: give the file a structured `stop_rule: {doctrine, anchor_at}` mapping when a
  229	     * second doctrine needs a handover.
  230	     *
  231	     * @param  array<string, array{anchor: array{unit: string, count: int}, ratio: array<string, int>, stop_rule?: string}>  $doctrines
  232	     * @param  array<string, UnitObject>  $defenceObjects
  233	     */
  234	    private function afterStopRule(array $doctrines, array $defenceObjects, string $key, PlanetService $planet): string
  235	    {
  236	        $rule = $doctrines[$key]['stop_rule'] ?? null;
  237	        if (!is_string($rule) || preg_match('/swap to ([a-z_]+) once the wall passes (\d+)/', $rule, $matches) !== 1) {
  238	            return $key;
  239	        }

