 3	namespace Modules\AI\Actions;
 4	
 5	use Exception;
 6	use Modules\AI\Contracts\QueueAiUnits;
 7	use Modules\AI\Domain\Decision\DefenseCompositionPlanner;
 8	use Modules\AI\Enums\AiQueueActionReason;
 9	use Modules\AI\Support\AiActionResult;
10	use OGame\Factories\PlanetServiceFactory;
11	use OGame\GameObjects\Models\Enums\GameObjectType;
12	use OGame\Models\Planet;
13	use OGame\Models\UnitQueue;
14	use OGame\Services\ObjectService;
15	use OGame\Services\PlanetService;
16	use OGame\Services\PlayerGameStateService;
17	use OGame\Services\UnitQueueService;
18	
19	/**
20	 * Module-owned adapter over the normal OGameX unit queue.
21	 *
22	 * The decision is the module's; the queue, its requirements and its prices are the host's. The host
23	 * service silently returns when the amount is unaffordable, so the planner must have already asked
24	 * what the planet can pay for -- this adapter only refuses what the host would never accept as a
25	 * unit, and reports whether a queue row actually appeared.
26	 */
27	class QueueAiUnitsAction implements QueueAiUnits
28	{
29	    public function __construct(
30	        private PlayerGameStateService $playerGameStateService,
31	        private PlanetServiceFactory $planetServiceFactory,
32	        private UnitQueueService $unitQueueService,
33	    ) {
34	    }
35	
36	    public function handle(int $playerId, int $planetId, int $unitId, int $amount): AiActionResult
37	    {
38	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
39	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
40	        }
41	
42	        if ($amount < 1) {
43	            return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
44	        }
45	
46	        try {
47	            $player = $this->playerGameStateService->advance($playerId, $planetId);
48	
49	            if ($player->isBanned()) {
50	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
51	            }
52	            if ($player->isInVacationMode()) {
53	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
54	            }
55	
56	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
57	            $unit = ObjectService::getObjectById($unitId);
58	            if ($unit->type !== GameObjectType::Ship && $unit->type !== GameObjectType::Defense) {
59	                return AiActionResult::rejected(AiQueueActionReason::NotAUnit);
60	            }
61	
62	            if ($unit->type === GameObjectType::Defense) {
63	                $amount = $this->withinCeiling($planet, $amount);
64	                if ($amount < 1) {
65	                    return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
66	                }
67	            }
68	
69	            $this->unitQueueService->add($planet, $unitId, $amount);
70	            $queueId = UnitQueue::query()
71	                ->where('planet_id', $planetId)
72	                ->where('object_id', $unitId)
73	                ->where('processed', 0)
74	                ->latest('id')
75	                ->value('id');
76	
77	            return $queueId === null ? AiActionResult::rejected(AiQueueActionReason::QueueNotCreated) : AiActionResult::queued($queueId);
78	        } catch (Exception $exception) {
79	            return AiActionResult::rejected($exception->getMessage());
80	        }
81	    }
82	
83	    /**
84	     * The order trimmed to what the planet's standing wall has left of the behaviour file's ceiling.
85	     *
86	     * The planner refuses a wall at the ceiling, but a session backlog lets several sessions order
87	     * the same shortfall before any order reaches the yard, and the host takes the whole price when
88	     * it does. The ceiling is therefore applied where the units are written, against the wall built
89	     * and paid for as it stands now.
90	     */
91	    private function withinCeiling(PlanetService $planet, int $amount): int
92	    {
93	        $remaining = app(DefenseCompositionPlanner::class)->remainingCeiling($planet);
94	
95	        return $remaining === null ? $amount : min($amount, max(0, $remaining));
96	    }
97	}

